#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

run_wizard() {

TOTAL_STAGES=8

# PROTOTYPE (#137): sets up iCloud and CloudKit for the CK Spike harness only.
SPIKE_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
APP_DIR="$(cd "$SPIKE_DIR/../.." && pwd)"
ENV_FILE="$SPIKE_DIR/.env"   # gitignored
BUNDLE_ID="com.season42.app.cloudkitspike"
CONTAINER_ID="iCloud.$BUNDLE_ID"
export DEVELOPER_DIR="${DEVELOPER_DIR:-/Applications/Xcode.app/Contents/Developer}"
DERIVED="$SPIKE_DIR/DerivedData"
ENTITLEMENTS="$SPIKE_DIR/Config/CloudKitSpike.entitlements"
INFO_PLIST="$SPIKE_DIR/Config/Info.plist"
LOCAL_XCCONFIG="$APP_DIR/Config/Local.xcconfig"

spike_build() { # spike_build DESTINATION
  xcodebuild -project "$SPIKE_DIR/CloudKitSpike.xcodeproj" -scheme CloudKitSpike \
    -configuration Debug -destination "$1" -derivedDataPath "$DERIVED" \
    -allowProvisioningUpdates build -quiet
}

banner "iCloud + CloudKit setup for the CK Spike (#137)"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Preflight: team, entitlements, Xcode account"
say "Checking what the repo already has on this branch."
team=$(sed -nE 's/^[[:space:]]*DEVELOPMENT_TEAM[[:space:]]*=[[:space:]]*([A-Z0-9]+).*/\1/p' "$LOCAL_XCCONFIG" 2>/dev/null | tail -n1)
if [[ -z "$team" ]]; then
  warn "No DEVELOPMENT_TEAM in $LOCAL_XCCONFIG."
  open_url "https://developer.apple.com/account#MembershipDetailsCard"
  step "Membership details → copy the Team ID (10 characters)."
  ask DEVELOPMENT_TEAM "Paste your Team ID:"
  [[ -f "$LOCAL_XCCONFIG" ]] || cp "$APP_DIR/Config/Local.xcconfig.example" "$LOCAL_XCCONFIG"
  if grep -qE '^[[:space:]]*DEVELOPMENT_TEAM' "$LOCAL_XCCONFIG"; then
    sed -i '' -E "s/^[[:space:]]*DEVELOPMENT_TEAM.*/DEVELOPMENT_TEAM = $DEVELOPMENT_TEAM/" "$LOCAL_XCCONFIG"
  else
    printf 'DEVELOPMENT_TEAM = %s\n' "$DEVELOPMENT_TEAM" >> "$LOCAL_XCCONFIG"
  fi
  printf '  %s✓ wrote%s DEVELOPMENT_TEAM → %s\n' "$GREEN" "$RESET" "$LOCAL_XCCONFIG"
  team="$DEVELOPMENT_TEAM"
fi
write_env DEVELOPMENT_TEAM "$team"
problems=0
if grep -q "<string>$CONTAINER_ID</string>" "$ENTITLEMENTS" && grep -q "<string>CloudKit</string>" "$ENTITLEMENTS"; then
  say "✓ entitlements: iCloud (CloudKit) with $CONTAINER_ID"
else warn "entitlements lack the iCloud container or CloudKit"; problems=1; fi
if grep -q "aps-environment" "$ENTITLEMENTS"; then say "✓ entitlements: push (aps-environment)"
else warn "entitlements lack aps-environment (push)"; problems=1; fi
if grep -q "remote-notification" "$INFO_PLIST"; then say "✓ Info.plist: background mode remote-notification"
else warn "Info.plist lacks UIBackgroundModes remote-notification"; problems=1; fi
if (( problems )); then
  warn "Fix those in Xcode first: target → Signing & Capabilities → + Capability → iCloud (tick CloudKit and $CONTAINER_ID), Push Notifications, Background Modes (Remote notifications)."
  warn "Then check the pbxproj diff for a DEVELOPMENT_TEAM line Xcode may have added (see app/README.md), and remove it."
  pause "Press Enter when they're fixed"
fi
say ""
say "xcodebuild -allowProvisioningUpdates (stage 7) signs with the Apple ID that Xcode knows about."
step "Xcode → Settings → Accounts: make sure the Apple ID for team $team is listed and isn't asking you to sign in again."
pause "Press Enter once Xcode has your developer account"

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Developer portal: create the iCloud container"
say "The spike uses its own container, so it never touches the real app's data."
note "If you've built the spike for a device before, Xcode may have created it already. Then just check it's listed."
open_url "https://developer.apple.com/account/resources/identifiers/list/cloudContainer"
step "Certificates, Identifiers & Profiles → Identifiers, filtered to iCloud Containers."
step "If $CONTAINER_ID is listed, you're done here."
step "Otherwise click the blue + next to Identifiers → iCloud Containers → Continue."
step "Description: Season42 CloudKit spike"
step "Identifier: $CONTAINER_ID   (if the field already shows 'iCloud.', type only the rest)"
step "Continue → Register."
warn "Container IDs can't be deleted or reused, so check the spelling before you click Register."
pause "Press Enter when $CONTAINER_ID is in the list"

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Developer portal: App ID with iCloud + Push"
open_url "https://developer.apple.com/account/resources/identifiers/list"
step "Look for $BUNDLE_ID (Xcode-made ones are named like 'XC com season42 app cloudkitspike')."
step "If it's missing: + → App IDs → App → Continue → Explicit Bundle ID: $BUNDLE_ID, Description: CK Spike."
step "Under Capabilities, tick iCloud and choose 'Include CloudKit support'."
step "Tick Push Notifications. No certificate needed: CloudKit sends its own pushes."
step "Save (or Continue → Register for a new one)."
step "Open the App ID again → iCloud row → Edit/Configure → tick $CONTAINER_ID → Continue → Save."
note "Changing capabilities invalidates existing profiles for this App ID. Stage 7 makes a new one."
pause "Press Enter when the App ID has iCloud (with the container) and Push Notifications"

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Real iPhone: connect and pick it"
say "Sync between two simulators is unreliable, so one side is a real device."
step "Plug the iPhone in and unlock it. Tap Trust on 'Trust This Computer?' if it asks."
step "On the iPhone: Settings → Privacy & Security → Developer Mode → On (it restarts; confirm after)."
pause "Press Enter when the phone is connected and in Developer Mode"
say ""
say "Physical devices Xcode can see:"
xcrun devicectl list devices 2>/dev/null | awk 'NR<=2 || /physical/' | sed 's/^/    /' || warn "devicectl failed. Is Xcode installed at $DEVELOPER_DIR?"
ask CK_DEVICE_UDID "Paste the iPhone's Identifier (UDID):"
write_env CK_DEVICE_UDID "$CK_DEVICE_UDID"
note "Automatic signing adds the phone to your team's devices in stage 7."
pause

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "iPhone: sign into iCloud"
say "Both sides must use the SAME Apple ID: the spike syncs through that account's private database."
note "Any Apple ID works, since data goes only to the spike's development container. A dedicated test account keeps your own iCloud clean."
step "On the iPhone: Settings → [your name] at the top. If it's another Apple ID, sign out first."
step "Sign in with the test Apple ID and approve the two-factor code."
step "Settings → [name] → iCloud: make sure iCloud Drive is on."
ask CK_APPLE_ID "Which Apple ID did you use? (email, for your notes):"
write_env CK_APPLE_ID "$CK_APPLE_ID"
pause "Press Enter when the iPhone is signed in"

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "Simulator: boot one and sign into iCloud"
say "Available iOS simulators (the spike needs iOS 26.0 or later):"
xcrun simctl list devices available | awk '/^-- iOS 2[6-9]/{p=1;print "    "$0;next} /^--/{p=0} p{print "    "$0}'
ask CK_SIM_UDID "Paste the simulator's UDID:"
write_env CK_SIM_UDID "$CK_SIM_UDID"
xcrun simctl boot "$CK_SIM_UDID" 2>/dev/null || note "(already booted)"
open -a Simulator || warn "couldn't open Simulator.app; open it by hand"
step "In the simulator: Settings → Sign in to your iPhone → $CK_APPLE_ID."
step "Approve the two-factor code on a trusted device, then wait for the setup to finish."
step "Settings → [name] → iCloud: make sure iCloud Drive is on."
note "If sign-in hangs, Device → Restart and try again. That's common in the simulator."
pause "Press Enter when the simulator shows $CK_APPLE_ID at the top of Settings"

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "Signed device build: profile with iCloud + Push"
say "A device build makes Xcode fetch a development profile with the new capabilities."
say "It fails if the portal's App ID or container is wrong, so it checks stages 2–3."
note "Command: xcodebuild … -destination id=$CK_DEVICE_UDID -allowProvisioningUpdates build"
if confirm "Run the device build now?"; then
  if spike_build "id=$CK_DEVICE_UDID"; then
    say "✓ device build signed."
    app="$DERIVED/Build/Products/Debug-iphoneos/CloudKitSpike.app"
    ents=$(codesign -d --entitlements :- "$app" 2>/dev/null || true)
    for want in "$CONTAINER_ID" aps-environment; do
      if [[ "$ents" == *"$want"* ]]; then say "✓ signed app has $want"
      else warn "signed app lacks $want: check stage 3"; fi
    done
  else
    warn "Build failed. Usual causes: Xcode not signed in (stage 1), App ID missing iCloud/Push or container not ticked (stage 3)."
    SKIPPED+=("signed device build: fix and re-run the wizard")
  fi
else
  SKIPPED+=("signed device build (stage 7)")
fi
pause

# ── 8 ─────────────────────────────────────────────────────────────────────
stage "Smoke test: CK Spike on both sides"
say "Installs and launches CK Spike on the iPhone and the simulator to check the iCloud account."
warn "Nothing reaches CloudKit in this stage: sync is off by default and the store is empty."
note "The Console stays empty until you seed and turn sync on. The commands for that come at the end."
if confirm "Build, install and launch on both now?"; then
  dev_app="$DERIVED/Build/Products/Debug-iphoneos/CloudKitSpike.app"
  sim_app="$DERIVED/Build/Products/Debug-iphonesimulator/CloudKitSpike.app"
  if [[ -d "$dev_app" ]] || spike_build "id=$CK_DEVICE_UDID"; then
    if xcrun devicectl device install app --device "$CK_DEVICE_UDID" "$dev_app" >/dev/null &&
       xcrun devicectl device process launch --device "$CK_DEVICE_UDID" "$BUNDLE_ID" >/dev/null; then
      say "✓ launched on the iPhone"
    else warn "couldn't install or launch on the iPhone (is it unlocked?)"; SKIPPED+=("launch on iPhone"); fi
  else
    SKIPPED+=("iPhone build")
  fi
  if spike_build "id=$CK_SIM_UDID"; then
    if xcrun simctl install "$CK_SIM_UDID" "$sim_app" && xcrun simctl launch "$CK_SIM_UDID" "$BUNDLE_ID" >/dev/null; then
      say "✓ launched in the simulator"
    else warn "couldn't install or launch in the simulator"; SKIPPED+=("launch in simulator"); fi
  else
    SKIPPED+=("simulator build")
  fi
else
  SKIPPED+=("smoke test (stage 8)")
fi
say ""
step "On each side, the 'iCloud account' row should say the account is available."
step "If it says NO ACCOUNT, redo stage 5 or 6. If the iPhone says 'Untrusted Developer': Settings → General → VPN & Device Management → trust it."
pause "Press Enter to finish"

finish
say "${BOLD}Next: put data in CloudKit${RESET} (README protocol, question 2):"
say ""
say "  # 1. iPhone: seed with sync off"
say "  xcrun devicectl device process launch --device $CK_DEVICE_UDID --terminate-existing $BUNDLE_ID -- -syncOn NO -seedIfEmpty YES"
say "  # 2. iPhone: relaunch with sync on, wait for 'export succeeded' under CloudKit events"
say "  xcrun devicectl device process launch --device $CK_DEVICE_UDID --terminate-existing $BUNDLE_ID -- -syncOn YES"
say "  # 3. Simulator: import from CloudKit (question 1)"
say "  xcrun simctl launch --terminate-running-process $CK_SIM_UDID $BUNDLE_ID -syncOn YES"
say ""
note "devicectl needs the -- before the app's arguments; simctl doesn't. Run with DEVELOPER_DIR=$DEVELOPER_DIR."
note "Then in the CloudKit Console ($CONTAINER_ID → Development):"
note "  Schema → Record Types lists CD_TrackedSeries, CD_TrackedMovie, CD_StreamingService."
note "  Records → Private database → zone com.apple.coredata.cloudkit.zone (not _defaultZone),"
note "  signed in as $CK_APPLE_ID. A 'recordName is not marked queryable' error means adding a"
note "  Queryable index on recordName under Schema → Indexes (only the Console needs it)."
say ""
say "Full protocol: $SPIKE_DIR/README.md"
note "Values saved in $ENV_FILE. Load them with: set -a; source $ENV_FILE; set +a"
}

run_wizard "$@"; exit
